macro_rules! add_regex_redactions {
    () => {
        fn add_regex_redactions (subs : & mut snapbox :: Redactions) { subs . insert ("[ELAPSED]" , regex ! (r"\[FINISHED\].*in (?<redacted>[0-9]+(\.[0-9]+)?(m [0-9]+)?)s") ,) . unwrap () ; subs . insert ("[ELAPSED]" , regex ! (r"Finished.*in (?<redacted>[0-9]+(\.[0-9]+)?(m [0-9]+)?)s") ,) . unwrap () ; subs . insert ("[ELAPSED]" , regex ! (r"; finished in (?<redacted>[0-9]+(\.[0-9]+)?(m [0-9]+)?)s") ,) . unwrap () ; subs . insert ("[FILE_NUM]" , regex ! (r"\[(REMOVED|SUMMARY)\] (?<redacted>[1-9][0-9]*) files") ,) . unwrap () ; subs . insert ("[FILE_SIZE]" , regex ! (r"(?<redacted>[0-9]+(\.[0-9]+)?([a-zA-Z]i)?)B\s") ,) . unwrap () ; subs . insert ("[HASH]" , regex ! (r"home/\.cargo/registry/(cache|index|src)/-(?<redacted>[a-z0-9]+)") ,) . unwrap () ; subs . insert ("[HASH]" , regex ! (r"\.cargo/target/(?<redacted>[0-9a-f]{2}/[0-9a-f]{14})") ,) . unwrap () ; subs . insert ("[HASH]" , regex ! (r"/[a-z0-9\-_]+-(?<redacted>[0-9a-f]{16})")) . unwrap () ; subs . insert ("[HASH]" , regex ! (r"/(?<redacted>[a-f0-9]{2}\/[0-9a-f]{14})")) . unwrap () ; subs . insert ("[HASH]" , regex ! (r"[a-z0-9]+-(?<redacted>[a-f0-9]{16})")) . unwrap () ; subs . insert ("[HASH]" , regex ! (r"\/(?<redacted>[0-9a-f]{16})\/")) . unwrap () ; subs . insert ("[AVG_ELAPSED]" , regex ! (r"(?<redacted>[0-9]+(\.[0-9]+)?) ns/iter") ,) . unwrap () ; subs . insert ("[JITTER]" , regex ! (r"ns/iter \(\+/- (?<redacted>[0-9]+(\.[0-9]+)?)\)") ,) . unwrap () ; subs . insert ("[TIME_DIFF_AFTER_LAST_BUILD]" , regex ! (r"(?<redacted>[0-9]+(\.[0-9]+)?s, (\s?[0-9]+(\.[0-9]+)?(s|ns|h))+ after last build at [0-9]+(\.[0-9]+)?s)") ,) . unwrap () ; }
    };
}

add_regex_redactions!()